/** Translates VT100 special-graphics (G0/G1 line-drawing) code points to Unicode. */
private static int translateLineDrawingCodePoint(int codePoint) {
    // http://www.vt100.net/docs/vt102-ug/table5-15.html.
    switch (codePoint) {
        case '_': return ' ';    // Blank.
        case '`': return '◆';   // Diamond.
        case '0': return '█';   // Solid block.
        case 'a': return '▒';   // Checker board.
        case 'b': return '␉';   // Horizontal tab.
        case 'c': return '␌';   // Form feed.
        case 'd': return '\r';  // Carriage return.
        case 'e': return '␊';   // Linefeed.
        case 'f': return '°';   // Degree.
        case 'g': return '±';   // Plus-minus.
        case 'h': return '\n';  // Newline.
        case 'i': return '␋';   // Vertical tab.
        case 'j': return '┘';   // Lower right corner.
        case 'k': return '┐';   // Upper right corner.
        case 'l': return '┌';   // Upper left corner.
        case 'm': return '└';   // Left left corner.
        case 'n': return '┼';   // Crossing lines.
        case 'o': return '⎺';   // Horizontal line - scan 1.
        case 'p': return '⎻';   // Horizontal line - scan 3.
        case 'q': return '─';   // Horizontal line - scan 5.
        case 'r': return '⎼';   // Horizontal line - scan 7.
        case 's': return '⎽';   // Horizontal line - scan 9.
        case 't': return '├';   // T facing rightwards.
        case 'u': return '┤';   // T facing leftwards.
        case 'v': return '┴';   // T facing upwards.
        case 'w': return '┬';   // T facing downwards.
        case 'x': return '│';   // Vertical line.
        case 'y': return '≤';   // Less than or equal to.
        case 'z': return '≥';   // Greater than or equal to.
        case '{': return 'π';   // Pi.
        case '|': return '≠';   // Not equal to.
        case '}': return '£';   // UK pound.
        case '~': return '·';   // Centered dot.
        default:  return codePoint;
    }
}

private void setCursorRow(int row) {
    mCursorRow = row;
    mAboutToAutoWrap = false;
}

private void setCursorCol(int col) {
    mCursorCol = col;
    mAboutToAutoWrap = false;
}

/** Set the cursor mode, but limit it to margins if {@link #DECSET_BIT_ORIGIN_MODE} is enabled. */
private void setCursorColRespectingOriginMode(int col) {
    setCursorPosition(col, mCursorRow);
}

/** Sets the cursor to an absolute (row, col) position, ignoring {@link #DECSET_BIT_ORIGIN_MODE}. */
private void setCursorRowColAbsolute(int row, int col) {
    mCursorRow = Math.max(0, Math.min(row, mRows - 1));
    mCursorCol = Math.max(0, Math.min(col, mColumns - 1));
    mAboutToAutoWrap = false;
}

public int getScrollCounter() {
    return mScrollCounter;
}

public void clearScrollCounter() {
    mScrollCounter = 0;
}

public boolean isAutoScrollDisabled() {
    return mAutoScrollDisabled;
}

public void toggleAutoScrollDisabled() {
    mAutoScrollDisabled = !mAutoScrollDisabled;
}


/** Reset terminal state so user can interact with it regardless of present state. */
public void reset() {
    setCursorStyle();
    mArgIndex = 0;
    mContinueSequence = false;
    mEscapeState = ESC_NONE;
    mInsertMode = false;
    mTopMargin = mLeftMargin = 0;
    mBottomMargin = mRows;
    mRightMargin = mColumns;
    mAboutToAutoWrap = false;
    mForeColor = mSavedStateMain.mSavedForeColor = mSavedStateAlt.mSavedForeColor = TextStyle.COLOR_INDEX_FOREGROUND;
    mBackColor = mSavedStateMain.mSavedBackColor = mSavedStateAlt.mSavedBackColor = TextStyle.COLOR_INDEX_BACKGROUND;
    setDefaultTabStops();

    mUseLineDrawingG0 = mUseLineDrawingG1 = false;
    mUseLineDrawingUsesG0 = true;

    mSavedStateMain.mSavedCursorRow = mSavedStateMain.mSavedCursorCol = mSavedStateMain.mSavedEffect = mSavedStateMain.mSavedDecFlags = 0;
    mSavedStateAlt.mSavedCursorRow = mSavedStateAlt.mSavedCursorCol = mSavedStateAlt.mSavedEffect = mSavedStateAlt.mSavedDecFlags = 0;
    mCurrentDecSetFlags = 0;
    // Initial wrap-around is not accurate but makes terminal more useful, especially on a small screen:
    setDecsetinternalBit(DECSET_BIT_AUTOWRAP, true);
    setDecsetinternalBit(DECSET_BIT_CURSOR_ENABLED, true);
    mSavedDecSetFlags = mSavedStateMain.mSavedDecFlags = mSavedStateAlt.mSavedDecFlags = mCurrentDecSetFlags;

    // XXX: Should we set terminal driver back to IUTF8 with termios?
    mUtf8Index = mUtf8ToFollow = 0;

    mColors.reset();
    mSession.onColorsChanged();
}

public String getSelectedText(int x1, int y1, int x2, int y2) {
    return mScreen.getSelectedText(x1, y1, x2, y2);
}

