                    setOrClear = false;
                    break;
                case 25: // No blink.
                    bits = TextStyle.CHARACTER_ATTRIBUTE_BLINK;
                    setOrClear = false;
                    break;
                case 27: // Positive image.
                    bits = TextStyle.CHARACTER_ATTRIBUTE_INVERSE;
                    setOrClear = false;
